DATA.eras = [{"from":1502.0,"to":1519.3014,"name":"The Fifth Sun","title":"The empire at its height — and its fracture lines","text":"From 1502 Moctezuma II rules a Triple Alliance taking tribute from some 38 provinces — a network of obligations over local dynasts, not a bordered state. Inside it: recently conquered peoples with living memories of independence. Outside it: unconquered Tlaxcallan, blockaded and waiting. The map's colours are the fracture lines the war will follow.","image":{"src":"img/cards/mendoza-founding.jpg","caption":"Codex Mendoza fol. 2r: the eagle on the nopal — the founding of Tenochtitlan, painted by Nahua scribes c. 1541","credit":"Bodleian Library MS. Arch. Selden. A. 1, public domain, via Wikimedia Commons"},"chapterEvents":[{"t":1502.7041,"name":"Moctezuma II becomes huey tlatoani","id":"moctezuma-accession"},{"t":1507.8712,"name":"The last New Fire ceremony","id":"new-fire-1507"},{"t":1509.4137,"name":"The omens later remembered","id":"omens-reported"},{"t":1511.4137,"name":"The empire's last expansion: Tlachquiauhco","id":"tlachquiauhco-1511"},{"t":1515.4137,"name":"Nezahualpilli of Texcoco dies; the succession splits","id":"nezahualpilli-dies"},{"t":1517.1616,"name":"Córdoba's expedition touches Yucatán","id":"cordoba-1517"},{"t":1518.4137,"name":"Grijalva coasts the Gulf; first embassies","id":"grijalva-1518"},{"t":1519.1315,"name":"The company leaves Cuba","id":"depart-cuba"},{"t":1519.2274,"name":"Battle of Centla","id":"centla"}],"nEvents":9},{"from":1519.3014,"to":1519.8521,"name":"Landfall","title":"The corridor: Cempoala, Tlaxcallan, Cholula","text":"A private expedition of a few hundred, illegal from its first day, lands inside the tribute province of Cuetlaxtlan. What turns it into a war is not steel but politics: the Totonac tribute grievance, then — after two weeks of hard fighting — the Tlaxcala alliance. The column that climbs to the Basin in November is already mostly Nahua.","image":{"src":"img/cards/lienzo-meeting.jpg","caption":"The Lienzo de Tlaxcala: Cortés and the lords of Tlaxcallan — Malintzin interpreting at the centre","credit":"Lienzo de Tlaxcala (c. 1552), public domain, via Wikimedia Commons"},"chapterEvents":[{"t":1519.3014,"name":"Landing at San Juan de Ulúa","id":"ulua-landing"},{"t":1519.4877,"name":"Villa Rica de la Vera Cruz founded; the legal coup","id":"villa-rica-founded"},{"t":1519.5342,"name":"Cempoala seizes Moctezuma's tribute collectors","id":"cempoala-tribute-refusal"},{"t":1519.6055,"name":"The ships are run ashore","id":"ships-scuttled"},{"t":1519.6219,"name":"The march inland begins","id":"march-inland"},{"t":1519.6685,"name":"Tlaxcallan fights the company","id":"tlaxcala-battles"},{"t":1519.726,"name":"The Tlaxcala alliance","id":"tlaxcala-alliance"},{"t":1519.7945,"name":"The Cholula massacre","id":"cholula-massacre"},{"t":1519.8137,"name":"Ordaz climbs the smoking mountain","id":"ordaz-popocatepetl"},{"t":1519.8329,"name":"Cholula realigned under coalition lords","id":"cholula-realigned"}],"nEvents":12},{"from":1519.8521,"to":1520.388,"name":"The hostage regime","title":"An empire ruled through a captive centre","text":"Received as guests on 8 November, the Spaniards seize Moctezuma within the week and rule through him for six months. Tribute keeps flowing; the provinces watch; Texcoco's succession crisis deepens. The system's obedience to its centre is the weapon turned against it.","image":{"src":"img/cards/moctezuma.jpg","caption":"Moctezuma II as the 17th century imagined him — a portrait of memory, not of life","credit":"attr. school of Antonio Rodríguez, public domain, via Wikimedia Commons"},"chapterEvents":[{"t":1519.8521,"name":"The company enters Tenochtitlan; Moctezuma receives Cortés","id":"entry-tenochtitlan"},{"t":1519.8685,"name":"Moctezuma seized in his own city","id":"moctezuma-seized"},{"t":1519.9151,"name":"Quauhpopoca burned before the palace","id":"quauhpopoca-burned"},{"t":1520.0383,"name":"Cacama of Texcoco arrested; Acolhua politics captured","id":"cacama-arrested"},{"t":1520.2022,"name":"The treasure of generations goes into the crucible","id":"gold-melted"},{"t":1520.3005,"name":"Narváez lands to arrest Cortés","id":"narvaez-lands"}],"nEvents":6},{"from":1520.388,"to":1520.4973,"name":"Rupture","title":"Tóxcatl, the rising, the Noche Triste","text":"Alvarado's massacre of the Tóxcatl celebrants ends the hostage regime in blood. The city rises, Moctezuma dies in Spanish custody — by whose hand is disputed to this day — and on the night of 30 June the company is destroyed on the Tlacopan causeway. The coalition survives because Tlaxcallan chooses to keep it alive.","image":{"src":"img/cards/noche-triste.jpg","caption":"The Sad Night, from the 17th-century Conquest of Mexico series: the causeway fight under a crescent moon","credit":"17th-c. oil, Library of Congress (Kislak), public domain, via Wikimedia Commons"},"chapterEvents":[{"t":1520.388,"name":"The Tóxcatl massacre","id":"toxcatl"},{"t":1520.4044,"name":"Cortés surprises Narváez at Cempoala","id":"cempoala-narvaez"},{"t":1520.4781,"name":"Cortés re-enters a risen city","id":"cortes-returns"},{"t":1520.4945,"name":"Death of Moctezuma II","id":"moctezuma-dies"}],"nEvents":4},{"from":1520.4973,"to":1520.9973,"name":"The plague year","title":"Smallpox, Tepeaca, and the war for the corridor","text":"Smallpox, landed with the Narváez fleet, burns through a hemisphere with no immunity — killing, among uncounted others, the new huey tlatoani Cuitláhuac, on the defending side only. The coalition retakes the eastern road by terror. The epidemic is not scenery: it is a combatant, and the model draws its mortality as the wide band it honestly is.","image":{"src":"img/cards/fc-smallpox.jpg","caption":"Book XII: a healer tends smallpox victims, drawn by Nahua artists who lived the epidemic's aftermath","credit":"Florentine Codex, Biblioteca Medicea Laurenziana, public domain, via Wikimedia Commons"},"chapterEvents":[{"t":1520.4973,"name":"The Noche Triste: the flight from Tenochtitlan","id":"noche-triste"},{"t":1520.5137,"name":"Battle of Otompan (Otumba)","id":"otumba"},{"t":1520.5246,"name":"Tlaxcallan holds: the pact renewed","id":"tlaxcala-refuge"},{"t":1520.7077,"name":"Cuitláhuac becomes huey tlatoani","id":"cuitlahuac-tlatoani"},{"t":1520.6749,"name":"The Tepeaca campaign; Segura de la Frontera","id":"tepeaca-campaign"},{"t":1520.7049,"name":"The branding iron at Tepeyacac","id":"tepeaca-enslavement"},{"t":1520.7869,"name":"Cuauhquechollan turns on its garrison","id":"cuauhquechollan-defects"},{"t":1520.7486,"name":"Smallpox reaches the Basin","id":"smallpox-basin"},{"t":1520.9235,"name":"Cuitláhuac dies of smallpox; Cuauhtémoc chosen","id":"cuitlahuac-dies"}],"nEvents":9},{"from":1520.9973,"to":1521.3863,"name":"The ring closes","title":"Texcoco changes sides; the lake is prepared","text":"On the last day of 1520 the alliance's second capital passes to the coalition — Acolhua manpower, food, and a shipyard. Chalco follows, then the circuits: north around the lakes, south through Cuauhnáhuac and Xochimilco. Thirteen brigantines are carried overland in pieces and launched. The siege exists before it begins.","image":{"src":"img/cards/ring-closes.jpg","caption":"The ring closing on the island: the causeway camps and the brigantines, in a late-17th-c. retelling","credit":"'Conquista de México' series, public domain, via Wikimedia Commons"},"chapterEvents":[{"t":1520.9973,"name":"The coalition enters Texcoco","id":"texcoco-taken"},{"t":1521.0219,"name":"Iztapalapan burned","id":"iztapalapa-burned"},{"t":1521.0521,"name":"The Chalca towns come over","id":"chalco-defects"},{"t":1521.1233,"name":"The northern circuit: Xaltocan to Tlacopan","id":"xaltocan-circuit"},{"t":1521.137,"name":"A fleet carried over the mountains","id":"brigantines-carried"},{"t":1521.2,"name":"The Mexica strike back at Chalco","id":"chalco-counterattacks"},{"t":1521.2575,"name":"Sandoval's relief: Chalco held","id":"chalco-relieved"},{"t":1521.2795,"name":"The southern circuit: Cuauhnáhuac and Xochimilco","id":"southern-circuit"},{"t":1521.2877,"name":"Two days in the canals of Xōchimīlco","id":"xochimilco-battle"},{"t":1521.3205,"name":"Thirteen brigantines launched at Texcoco","id":"brigantines-launched"}],"nEvents":10},{"from":1521.3863,"to":1521.6137,"name":"The siege","title":"Four arteries: causeways, aqueduct, lake, food","text":"Three camps seal the causeways; the Chapultepec aqueduct is cut on day four; the brigantines break the canoe fleet and the island starves. Perhaps 900 Spaniards and — by every account including Cortés's own — tens of thousands of Nahua allies unmake the city street by street. It ends on 13 August, the day 1 Cóatl, with Cuauhtémoc taken on the water.","image":{"src":"img/cards/map-1524.jpg","caption":"The 1524 Nuremberg woodcut: Tenochtitlan as Europe first saw it — schematic (best-fit residual 2.2 km), west at top","credit":"Newberry Library scan, public domain, via Wikimedia Commons"},"chapterEvents":[{"t":1521.3863,"name":"The siege opens: three causeway camps","id":"siege-camps"},{"t":1521.3973,"name":"The Chapultepec aqueduct is cut","id":"aqueduct-cut"},{"t":1521.4137,"name":"The lake is lost: the canoe fleet broken","id":"brigantine-victory"},{"t":1521.4384,"name":"The last road closed: Tepeyacac","id":"sandoval-tepeyac"},{"t":1521.4932,"name":"The great ambush: the siege's worst Spanish defeat","id":"tlatelolco-ambush"},{"t":1521.4959,"name":"Brackish water and the hunger","id":"water-famine"},{"t":1521.5205,"name":"The flanks secured: Malinalco and the Matlatzinca","id":"malinalco-expedition"},{"t":1521.5479,"name":"The city unmade street by street","id":"razing-advance"},{"t":1521.5616,"name":"The offers refused","id":"surrender-refused"},{"t":1521.5808,"name":"The last stand compresses into the market","id":"tlatelolco-market-fall"}],"nEvents":10},{"from":1521.6137,"to":1524.4153,"name":"The world remade","title":"The conquest does not end at the fall","text":"Mexico City rises on the razed grid; the provinces pass to the new regime — some by column, some by letter. Michoacán, never conquered by the Mexica, submits without a siege. The allies who won the war begin learning what they have won: encomienda, tribute reassessed, and lords hanged on suspicion.","image":{"src":"img/cards/mendoza-tribute.jpg","caption":"A Codex Mendoza tribute folio: town glyphs and their semi-annual dues in cloth, feathers and stone","credit":"Bodleian Library, public domain, via Wikimedia Commons"},"chapterEvents":[{"t":1521.6137,"name":"The fall: Cuauhtémoc taken on the water","id":"fall-tenochtitlan"},{"t":1521.6247,"name":"Cuauhtémoc tortured for the treasure","id":"cuauhtemoc-tortured"},{"t":1521.7041,"name":"The distribution of persons","id":"slaves-branded"},{"t":1521.7863,"name":"The victory banquet at Coyohuacan","id":"coyoacan-banquet"},{"t":1521.9534,"name":"The Oaxaca valley occupied","id":"oaxaca-taken"},{"t":1522.0384,"name":"Mexico City rises on the razed grid","id":"rebuilding-begins"},{"t":1522.1616,"name":"Alvarado takes Tototepec","id":"tototepec-taken"},{"t":1522.5342,"name":"The Purépecha state submits without a siege","id":"michoacan-submits"},{"t":1522.7863,"name":"The crown legalises the fact: Cortés governor","id":"cortes-governor"},{"t":1523.0384,"name":"The Pánuco campaign","id":"panuco-campaign"}],"nEvents":12},{"from":1524.4153,"to":1535.8685,"name":"Conquistador New Spain","title":"Friars, encomenderos, and wars that do not stop","text":"The Twelve arrive barefoot to replace a sacred order; Cuauhtémoc is hanged on the Honduras march; Guzmán burns the Purépecha cazonci and devastates the west. Native New Spain fights on both sides of every colonial war — the conquest continues under legal forms.","image":{"src":"img/cards/cortes.jpg","caption":"Cortés in a copy portrait inscribed 1525 — the commander as his own century painted him","credit":"anonymous copy portrait, public domain, via Wikimedia Commons"},"chapterEvents":[{"t":1524.4153,"name":"The Twelve arrive: the spiritual conquest begins","id":"franciscan-twelve"},{"t":1524.7787,"name":"The Honduras march leaves the valley","id":"honduras-march"},{"t":1525.1589,"name":"Cuauhtémoc hanged at Itzamkánac","id":"cuauhtemoc-executed"},{"t":1528.9372,"name":"The first audiencia: government as plunder","id":"first-audiencia"},{"t":1528.9536,"name":"Zumárraga, first bishop and 'Protector of the Indians'","id":"zumarraga-bishop"},{"t":1529.9671,"name":"Nuño de Guzmán's western march; the cazonci burned","id":"guzman-west"},{"t":1531.0247,"name":"The second audiencia begins the repair","id":"second-audiencia"},{"t":1531.4137,"name":"The Yope rising crushed","id":"yope-war"},{"t":1531.937,"name":"Tepeyacac: the apparition tradition","id":"guadalupe-tradition"}],"nEvents":9},{"from":1535.8685,"to":1551.0,"name":"Viceroyalty","title":"Bureaucratic empire and the vanishing lake","text":"Royal government arrives with Mendoza; the Mixtón war is put down with tens of thousands of Nahua troops; the cocoliztli of 1545-48 kills on a scale that dwarfs the siege. By 1550 the survivors are being gathered into planned towns and the lakes are shrinking — the world this model opened with is gone.","image":{"src":"img/cards/uppsala-map.jpg","caption":"The Uppsala map, c. 1550: Mexico City drawn by Nahua hands a generation after the fall — the world this model ends in","credit":"Mapa Uppsala (c. 1550), public domain, via Wikimedia Commons"},"chapterEvents":[{"t":1535.8685,"name":"Antonio de Mendoza, first viceroy","id":"mendoza-viceroy"},{"t":1536.0137,"name":"The Colegio de Santa Cruz opens at Tlatelolco","id":"colegio-tlatelolco"},{"t":1539.4137,"name":"The first printing press in the Americas","id":"printing-press"},{"t":1539.9123,"name":"Don Carlos of Texcoco burned for heresy","id":"don-carlos-executed"},{"t":1541.4137,"name":"The Codex Mendoza is painted","id":"codex-mendoza-made"},{"t":1541.6658,"name":"The Mixtón war","id":"mixton-war"},{"t":1542.8849,"name":"The New Laws: encomienda checked on paper","id":"new-laws"},{"t":1545.4137,"name":"The great cocoliztli","id":"cocoliztli-1545"},{"t":1547.4137,"name":"Sahagún begins collecting the elders' testimony","id":"sahagun-begins"},{"t":1550.0,"name":"Congregación: the map itself is remade","id":"congregacion-1550"}],"nEvents":10}];
